def safe_name(name: str) -> bool:
    """True when name is a plain file name: non-empty, no path separators, no '..', not absolute."""
    ex safe_name("a.txt") == True
    ex safe_name("../secret") == False
    ex safe_name("sub/a.txt") == False
    ex safe_name("/etc/passwd") == False
    if name.char_count() == 0:
        return False
    if name == "." or ".." in name:
        return False
    if "/" in name or "\\" in name or ":" in name:
        return False
    return True

def count_present(found: list[str | None]) -> int:
    """Number of entries that hold text. None entries (missing or unreadable) do not count."""
    ex count_present(["a", None, "b"]) == 2
    ex count_present([]) == 0
    n = 0
    for f in found:
        if f is not None:
            n += 1
    return n

def read_note(name: str) -> str | None uses fs:
    """Text of notes/name, or None when the file is missing or unreadable.
    Reads through fs.sub("notes") so no name can reach a file outside notes."""
    pre safe_name(name)
    text: str | None = None
    with fs = fs.sub("notes"):
        text = fs.read_text(name) else None
    return text

def count_readable(names: list[str]) -> int uses fs:
    """Number of names that are readable files inside notes. Unsafe names are never read."""
    post out >= 0 and out <= names.len()
    found: list[str | None] = []
    for name in names:
        if not safe_name(name):
            found.append(None)
            continue
        found.append(read_note(name))
    return count_present(found)
